INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('343329fb0a0b8cf92521','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','105','Mixed/Unclassified','Australian Medical Council
Section 2 — Trial Examination
MCQ 2.130
| A 24-year-old woman, who has previously had a normal vaginal delivery of a 3900g
| male infant at term, is found to have a breech presentation at 37 weeks gestation in
her second pregnancy. Ultrasound examination has shown the fetus has extended
__ legs. She is keen to deliver this baby vaginally if possible. Which one of the following
would be the most appropriate next step in management?
A. Caesarean section now.
B. Caesarean section at term.
C. X-ray pelvimetry.
D. Induction of labour at term.
E. Await spontaneous onset of labour.
MCQ 2.131
A 4-week-old boy presents with a 10-day history of vomiting that has increased in
frequency and forcefulness. The vomitus is not bile-stained but has a coffee-ground
appearance. The child feeds avidly and looks well, but he has been losing weight.
