INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('610d002805ac67f6262f','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','110','Mixed/Unclassified','Australian Medical Council
Section 2 — Trial Examination
MCQ 2.144','{"A":"His antihypertensive medications.","B":"Conn syndrome (primary hyperaldosteronism).","C":"A villous adenoma of the rectum.","D":"A carcinoma of the gastrointestinal tract.","E":"Congestive cardiac failure.\n\n———$———\n\nMCQ 2.145\n\nIn the assessment of the development of a child who has just turned three years old,\nwhich one of the following skills should he have already acquired?\n\nDress without supervision.\nDraw a recognisable man.\n. Tie shoelaces.\n\n. Hop on one foot.\n\nClimb stairs.\n\n————————\n\nMCQ 2.146\n\nMLO ZO 2095 >\n\nA 55-year-old man has made a serious attempt at suicide by cutting his throat. He\nhad been depressed for some time and had chronic pain from an osteoarthritic\nhip, which has prevented him from working as a taxi driver. His wife says that as a\nresult of the loss of income he erroneously believed that he is now bankrupt. After\nsurgical repair of his injury and a period of intensive care, he remains virtually mute,\nwithdrawn and psychomotor retarded. He has stopped eating and drinks only small\namounts. His family wish to take him home as they feel the hospital environment is\nmaking him worse. Which one of the following is the most appropriate management\nplane\n\nA. Discharge him home on antidepressant medication with daily reviews by his\ngeneral practitioner and the local mental health crisis team.\n\nB. Admission to a general medical ward, with intravenous fluids, antidepressants\nand a nursing special around the clock.\n\nC. Continue his stay in the intensive care unit with antidepressants and\nhyperalimentation and daily liaison psychiatric review.\n\nD. Admission to a psychiatric unit with antidepressant and antipsychotic\nmedication.\n\nE. Involuntary psychiatric hospitalisation for urgent electroconvulsive therapy (ECT)."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"2.144","duplicate_group_id":"exact-e80beb6aaf6d","duplicate_sources":[{"record_id":"610d002805ac67f6262f","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":110,"source_qid":"2.144"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"610d002805ac67f6262f","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":110,"source_qid":"2.144","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 2 — Trial Examination\nMCQ 2.144","options":{"A":"His antihypertensive medications.","B":"Conn syndrome (primary hyperaldosteronism).","C":"A villous adenoma of the rectum.","D":"A carcinoma of the gastrointestinal tract.","E":"Congestive cardiac failure.\n\n———$———\n\nMCQ 2.145\n\nIn the assessment of the development of a child who has just turned three years old,\nwhich one of the following skills should he have already acquired?\n\nDress without supervision.\nDraw a recognisable man.\n. Tie shoelaces.\n\n. Hop on one foot.\n\nClimb stairs.\n\n————————\n\nMCQ 2.146\n\nMLO ZO 2095 >\n\nA 55-year-old man has made a serious attempt at suicide by cutting his throat. He\nhad been depressed for some time and had chronic pain from an osteoarthritic\nhip, which has prevented him from working as a taxi driver. His wife says that as a\nresult of the loss of income he erroneously believed that he is now bankrupt. After\nsurgical repair of his injury and a period of intensive care, he remains virtually mute,\nwithdrawn and psychomotor retarded. He has stopped eating and drinks only small\namounts. His family wish to take him hom