MCQ 3.009
A 65-year-old man_ presents
with a three-day history of
a rash on his feet. He had
just completed a course of
trimethoprim for an attack of
prostatitis. He woke up with
the feet reddened and hot
and both feet seemed equally
involved. Over the next two
days his rash persisted and
there was blistering on both
sides. An illustration of his feet
is shown. The line markings
were made the previous day.
He has a history of chronic
arthritis of his knees and back,
for which he takes regular
paracetamol. He remembers
having arash with the same distribution after being treated for a urinary tract infection
some years ago. Which one of the following is the most likely diagnosis?','{"A":"SECTION 3: ADULT HEALTH AND AGED CARE","B":"| Medicine and Surgery","C":"3.010-3.024\nSystem 02","D":"AND NECK\nEYES\nEARS NOSE AND THROAT","E":"May include: ophthalmology, head and neck, otorhinolaryngology, pharynx, salivary\nglands."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[226,227],"source_qid":"3.009","duplicate_group_id":"exact-157f7e40f3bb","duplicate_sources":[{"record_id":"b55c6ea3419084988fc8","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":226,"source_qid":"3.009"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"b55c6ea3419084988fc8","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":226,"supporting_pages":[226,227],"source_qid":"3.009","domain_hint":"Mixed/Unclassified","stem":"Kustralian Medical Council\nMCQ 3.009\nA 65-year-old man_ presents\nwith a three-day history of\na rash on his feet. He had\njust completed a course of\ntrimethoprim for an attack of\nprostatitis. He woke up with\nthe feet reddened and hot\nand both feet seemed equally\ninvolved. Over the next two\ndays his rash persisted and\nthere was blistering on both\nsides. An illustration of his feet\nis shown. The line markings\nwere made the previous day.\nHe has a history of chronic\narthritis of his knees and back,\nfor which he takes regular\nparacetamol. He remembers\nhaving arash with the same distribution after being treated for a urinary tract infection\nsome years ago. Which one of the following is the most likely diagnosis?","options":{"A":"SECTION 3: ADULT HEALTH AND AGED CARE","B":"| Medicine and Surgery","C":"3.010-3.024\nSystem 02","D":"AND NECK\nEYES\nEARS NOSE AND THROAT","E":"May include: ophthalmology, head and neck, otorhinolaryngology, pharynx, salivary\nglands."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"157f7e40f3bbe2972e25b5d2db9776a4f02517f1","duplicate_group_id":"exact-157f7e40f3bb","duplicate_sources":[{"record_id":"b55c6ea3419084988fc8","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":226,"source_qid":"3.009"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
