INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('122e2f655c18691a230a','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','230','Mixed/Unclassified','Australian Medical Council
Section 3 — Adult Health and Aged Care
MCQ 3.015
You are examining a 20-year-old patient who is under observation after being hit
by a cricket ball on the right temple. He is stuporous and you note irregularity of the
pupils. On the right side there is a dilated pupil, together with loss of the right direct
and consensual light reflexes. The right pupil does not react to accommodation, but
the right corneal reflex is present. Left-sided pupil reflexes are normal. Which one of
the following right-sided cranial nerves is most likely to be affected?
. Second.
Third.
. Fourth.
. Fifth.
Sixth.
MCQ 3.016
MOG) 2 >
A 45-year-old man presents with a slowly enlarging neck lump. The lump, in the posterior
triangle lymph nodes of the neck in the midneck area, has had a percutaneous core
biopsy and the histological report is ‘metastatic squamous cell carcinoma in a lymph
node’. Which one of the following would be the most likely primary site if there were
no obvious skin lesions present?','{"A":"Buccal cavity.","B":"Tonsillar fossa.","C":"Larynx.","D":"Nasopharynx.","E":"Thyroid.\n\nMCQ 3.017\n\nThe 65-year-old patient (see illustrations) had a right carotid artery stenotic plaque\nremoved by carotid endarterectomy six weeks previously, at which time examination\nof the tongue and oral cavity was normal. Which one of the following is the most likely\ndiagnosis?"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.015","duplicate_group_id":"exact-643f80dac246","duplicate_sources":[{"record_id":"122e2f655c18691a230a","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":230,"source_qid":"3.015"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"122e2f655c18691a230a","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":230,"source_qid":"3.015","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3 — Adult Health and Aged Care\nMCQ 3.015\nYou are examining a 20-year-old patient who is under observation after being hit\nby a cricket ball on the right temple. He is stuporous and you note irregularity of the\npupils. On the right side there is a dilated pupil, together with loss of the right direct\nand consensual light reflexes. The right pupil does not react to accommodation, but\nthe right corneal reflex is present. Left-sided pupil reflexes are normal. Which one of\nthe following right-sided cranial nerves is most likely to be affected?\n. Second.\nThird.\n. Fourth.\n. Fifth.\nSixth.\nMCQ 3.016\nMOG) 2 >\nA 45-year-old man presents with a slowly enlarging neck lump. The lump, in the posterior\ntriangle lymph nodes of the neck in the midneck area, has had a percutaneous core\nbiopsy and the histological report is ‘metastatic squamous cell carcinoma in a lymph\nnode’. Which one of the following would be the most likely primary site if there were\nno obvious skin lesions present?","options":{"A":"Buccal cavity.","B":"Tonsillar fossa.","C":"Larynx.","D":"Nasopharynx.","E":"Thyroid.\n\nMCQ 3.017\n\nThe 65-year-old patient (see illustrations) had a right carotid artery stenotic plaque\nremoved by carotid endarterectomy six weeks previously, at which time examination\nof the tongue and oral cavity was normal. Which one of the following is the most likely\ndiagnosis?"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"643f80dac246e89bcec3587a1a59ae3faa086a49","duplicate_group_id":"exact-643f80dac246","duplicate_sources":[{"record_id":"122e2f655c18691a230a","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":230,"source_qid":"3.015"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.