INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8150caff5fff7cad9a80','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','235','Mixed/Unclassified','Australian Medical Council
Section 3— Adult Health and Aged Care
MCQ 3.025
A patient in a motor vehicle crash suffers a closed head injury. On recovery of
consciousness, she complains of double vision when she looks to the left. Vision ahead
is normal. Which one of the following cranial nerves is most likely to be damaged?
Right sixth nerve.
Left sixth nerve.
. Right fourth nerve.
Left fourth nerve.
Left third nerve.
MOQP>
MCQ 3.026
A 65-year-old woman presents in the evening with a three-hour history of acute pain
in the right eye, with blurred vision and seeing haloes around objects. On examination
the cornea is oedematous and hazy, the right pupil is irregular and the sclera injected.
Intraocular pressure is significantly raised at 25mmHg. Which one of the following
topical agents would be the most appropriate immediate treatment?
Atropine.
Physeptone.
. Chloramphenicol.
. Fluorocortisone.
Acetazolamide.
MTMMOQOP >
MCQ 3.027
A 50-year-old man presents with facial and eye muscular weakness. Which one of
the following physical signs is consistent with a diagnosis of acute Bell (seventh nerve)
palsy?','{"A":"Ptosis.","B":"Unilateral weakness of all facial muscles except frontalis.","C":"Deviation of the jaw on opening the mouth.","D":"Unilateral loss of taste.","E":"Unilateral loss of facial sweating.\n\nMCQ 3.028\n\nA 50-year-old man presents with a two-year history of burning pains in the feet, pins\nand needles in the fingers and toes, and weakness and unsteadiness of the legs.\nThere is distal wasting and weakness in alll limbs, glove and stocking sensory loss to alll\nmodalities, and areflexia. Which one of the following is the most likely diagnosis?\n\nPolymyositis.\n\nHereditary sensorimotor neuropathy (Charcot-Marie-Tooth disease).\n. Diabetic peripheral neuropathy.\n\nAcute infectious polyneuropathy (Guillain-Barré syndrome).\nDiabetic amyotrophy.\n\nMOQ2>"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.025","duplicate_group_id":"exact-539e780cb2a9","duplicate_sources":[{"record_id":"8150caff5fff7cad9a80","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":235,"source_qid":"3.025"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"8150caff5fff7cad9a80","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":235,"source_qid":"3.025","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3— Adult Health and Aged Care\nMCQ 3.025\nA patient in a motor vehicle crash suffers a closed head injury. On recovery of\nconsciousness, she complains of double vision when she looks to the left. Vision ahead\nis normal. Which one of the following cranial nerves is most likely to be damaged?\nRight sixth nerve.\nLeft sixth nerve.\n. Right fourth nerve.\nLeft fourth nerve.\nLeft third nerve.\nMOQP>\nMCQ 3.026\nA 65-year-old woman presents in the evening with a three-hour history of acute pain\nin the right eye, with blurred vision and seeing haloes around objects. On examination\nthe cornea is oedematous and hazy, the right pupil is irregular and the sclera injected.\nIntraocular pressure is significantly raised at 25mmHg. Which one of the following\ntopical agents would be the most appropriate immediate treatment?\nAtropine.\nPhyseptone.\n. Chloramphenicol.\n. Fluorocortisone.\nAcetazolamide.\nMTMMOQOP >\nMCQ 3.027\nA 50-year-old man presents with facial and eye muscular weakness. Which one of\nthe following physical signs is consistent with a diagnosis of acute Bell (seventh nerve)\npalsy?","options":{"A":"Ptosis.","B":"Unilateral weakness of all facial muscles except frontalis.","C":"Deviation of the jaw on opening the mouth.","D":"Unilateral loss of taste.","E":"Unilateral loss of facial sweating.\n\nMCQ 3.028\n\nA 50-year-old man presents with a two-year history of burning pains in the feet, pins\nand needles in the fingers and toes, and weakness and unsteadiness of the legs.\nThere is distal wasting and weakness in alll limbs, glove and stocking sensory loss to alll\nmodalities, and areflexia. Which one of the following is the most likely diagnosis?\n\nPolymyositis.\n\nHereditary sensorimotor neuropathy (Charcot-Marie-Tooth disease).\n. Diabetic peripheral neuropathy.\n\nAcute infectious polyneuropathy (Guillain-Barré syndrome).\nDiabetic amyotrophy.\n\nMOQ2>"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","treatment"],"likely_visual