INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('94777d796e967dce9ce2','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','236','Mixed/Unclassified','Australian Medical Council
‘Section 3 = Adult Health and Aged Care
STU REERaameeeeeeeeees eee
MCQ 3.029
A 25-year-old man presents with an acute history of sudden intense vertigo on waking,
with loss of balance affecting his left side and pain in the left ear. The sensation of the
environment rotating around him is associated with giddiness and ataxia, and with
vomiting, unless he lies completely still. There is no associated deafness or tinnitus.
On examination he has a nystagmus with the rapid component to the left. Cranial
nerve examination is otherwise normal. Caloric tests of vestibular function show
markedly reduced responses on the left side. Which one of the following is the most
likely diagnosis?','{"A":"A cerebellopontine angle tumour.","B":"Méniére disease.","C":"Vestibular neuronitis.","D":"Vertebrobasilar ischaemia.","E":"Paroxysmal positional vertigo.\n\nMC@Q 3.030\n\nA 65-year-old woman develops acute vertigo accompanied by nystagmus, a left\nHorner syndrome, and dissociated sensory loss affecting face and limbs. Which one\nof the following arteries is most likely to be occluded?\n\nA. Posterior inferior cerebellar artery.\nB. Anterior cerebral artery.\n\nC. Posterior cerebral artery.\n\nD. Internal carotid artery.\n\nE. Anterior communicating artery.\n\nMCQ 3.031\n\nIn establishing the diagnosis of brain death in a patient admitted to hospital comatose\nafter a massive stroke, which one of the following is the most important diagnostic\nclinical feature?\n\nIrreversible apnoea.\n\nFixed dilated pupils unresponsive to light.\n\n. Glasgow Coma Scale score of 3.\n\nComplete absence of response to painful stimuli.\nAbsence of activity on electroencephalography.\n\nMOQOP>\n\nMCQ 3.032\n\nA 74-year-old man is brought into the Emergency Department by his son. According\nto the son, his father is normally in good health, but has become rather forgetful over\nthe last few months. The father lives by himself and used to drink heavily, but has now\nreduced his intake to less than two standard drinks a day. Last week he fell and hurt\nhis head, but did not appear to be unduly shaken by the event. For the last few days\nthe patient has become increasingly confused. Which one of the following is the most\nlikely explanation for his current problem? |\n\na> |"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.029","duplicate_group_id":"exact-1738424b5bea","duplicate_sources":[{"record_id":"94777d796e967dce9ce2","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":236,"source_qid":"3.029"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"94777d796e967dce9ce2","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":236,"source_qid":"3.029","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\n‘Section 3 = Adult Health and Aged Care\nSTU REERaameeeeeeeeees eee\nMCQ 3.029\nA 25-year-old man presents with an acute history of sudden intense vertigo on waking,\nwith loss of balance affecting his left side and pain in the left ear. The sensation of the\nenvironment rotating around him is associated with giddiness and ataxia, and with\nvomiting, unless he lies completely still. There is no associated deafness or tinnitus.\nOn examination he has a nystagmus with the rapid component to the left. Cranial\nnerve examination is otherwise normal. Caloric tests of vestibular function show\nmarkedly reduced responses on the left side. Which one of the following is the most\nlikely diagnosis?","options":{"A":"A cerebellopontine angle tumour.","B":"Méniére disease.","C":"Vestibular neuronitis.","D":"Vertebrobasilar ischaemia.","E":"Paroxysmal positional vertigo.\n\nMC@Q 3.030\n\nA 65-year-old woman develops acute vertigo accompanied by nystagmus, a left\nHorner syndrome, and dissociated sensory loss affecting face and limbs. Which one\nof the following arteries is most likely to be occluded?\n\nA. Posterior inferior cerebellar artery.\nB. Anterior cerebral artery.\n\nC. Posterior cerebral artery.\n\nD. Internal carotid artery.\n\nE. Anterior communicating artery.\n\nMCQ 3.031\n\nIn establishing the diagnosis of brain death in a patient admitted to hospital comatose\nafter a massive stroke, which one of the following is the most important diagnostic\nclinical feature?\n\nIrreversible apnoea.\n\nFixed dilated pupils unresponsive to light.\n\n. Glasgow Coma Scale score of 3.\n\nComplete absence of response to painful stimuli.\nAbsence of activity on electroencephalography.\n\nMOQOP>\n\nMCQ 3.032\n\nA 74-year-old man is brought into the Emergency Department by his son. According\nto the son, his father is normally in good health, but has become rather forgetful over\nthe last few months. The father lives by himself and used to drink heavily, but has now\nreduced his intake to less than two standard drinks a day. Last week he fell and hurt\nhis head, but did not appear to be unduly shaken by the event. For the last few days\nthe patient has become increasingly confused. Which one of the following is the most\nlikely explanation for his current problem? |\n\na> |"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1738424b5beae38fee58ce616bc7d35efb756030","duplicate_group_id":"exact-1738424b5bea","duplicate_sources":[{"record_id":"94777d796e967dce9ce2","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":236,"source_qid":"3.029"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.so