INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('88ff1b530ec6ecd8bfc8','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','238','Mixed/Unclassified','Australian Medical Council
Section 3 — Adult Health and Aged Care
MCQ 3.036
In monitoring observations in patients after head injury, one should be aware that the
cardinal signs of rising intracranial pressure following a head injury are which one of the
following?','{"A":"Decreasing level of consciousness associated with bradycardia and\nhypertension.","B":"Sudden onset of coma with extensor responses.","C":"Decreasing level of consciousness associated with tachycardia and hypotension.","D":"Development of a confusional hyperexcitable state with tachycardia and\nhypertension.","E":"Development of Cheyne-Stokes breathing.\n\nMCQ 3.037\n\nA 20-year-old man sustains a lower thoracic spinal fracture-dislocation in a high-\nspeed motor injury. In checking his neurologic status below the level of injury, which\none of the following initial findings is most indicative of likely complete transection of\nthe spinal cord?\n\n. Loss of motor power but not of sensation.\nUpgoing (Babinski) plantar responses.\n. Flaccid paralysis and loss of all sensory modalities and reflexes.\n. Loss of sensation and power but not of leg reflexes.\nMotor spasticity and hyper-reflexia below the involved segments.\n\nFT: G)G): |? p>\n\nMCQ 3.038\n\nA 57-year-old woman presents with recurrent attacks of dizziness, with a sense of the\nroom spinning, associated with a progressive loss of hearing in the left ear. She has\nnoticed that her hearing is better when loud background noise is present. Audiology\nshows that there is a sensorineural loss in the affected ear. Which one of the following\nis the most likely cause of her symptoms?\n\nA\nB.\ni:\nD.\nE\n\n. An acoustic neuroma.\n\nOtosclerosis.\n\n. Méniére disease.\n\nVestibular neuronitis.\n\nPosterior inferior cerebellar artery thrombosis (PICA syndrome)."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.036","duplicate_group_id":"exact-ab9f8a507cb2","duplicate_sources":[{"record_id":"88ff1b530ec6ecd8bfc8","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":238,"source_qid":"3.036"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"88ff1b530ec6ecd8bfc8","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":238,"source_qid":"3.036","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3 — Adult Health and Aged Care\nMCQ 3.036\nIn monitoring observations in patients after head injury, one should be aware that the\ncardinal signs of rising intracranial pressure following a head injury are which one of the\nfollowing?","options":{"A":"Decreasing level of consciousness associated with bradycardia and\nhypertension.","B":"Sudden onset of coma with extensor responses.","C":"Decreasing level of consciousness associated with tachycardia and hypotension.","D":"Development of a confusional hyperexcitable state with tachycardia and\nhypertension.","E":"Development of Cheyne-Stokes breathing.\n\nMCQ 3.037\n\nA 20-year-old man sustains a lower thoracic spinal fracture-dislocation in a high-\nspeed motor injury. In checking his neurologic status below the level of injury, which\none of the following initial findings is most indicative of likely complete transection of\nthe spinal cord?\n\n. Loss of motor power but not of sensation.\nUpgoing (Babinski) plantar responses.\n. Flaccid paralysis and loss of all sensory modalities and reflexes.\n. Loss of sensation and power but not of leg reflexes.\nMotor spasticity and hyper-reflexia below the involved segments.\n\nFT: G)G): |? p>\n\nMCQ 3.038\n\nA 57-year-old woman presents with recurrent attacks of dizziness, with a sense of the\nroom spinning, associated with a progressive loss of hearing in the left ear. She has\nnoticed that her hearing is better when loud background noise is present. Audiology\nshows that there is a sensorineural loss in the affected ear. Which one of the following\nis the most likely cause of her symptoms?\n\nA\nB.\ni:\nD.\nE\n\n. An acoustic neuroma.\n\nOtosclerosis.\n\n. Méniére disease.\n\nVestibular neuronitis.\n\nPosterior inferior cerebellar artery thrombosis (PICA syndrome)."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ab9f8a507cb2868e4708af0f53cdda13a1255130","duplicate_group_id":"exact-ab9f8a507cb2","duplicate_sources":[{"record_id":"88ff1b530ec6ecd8bfc8","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":238,"source_qid":"3.036"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
