INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b76a7c605c194f014d54','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','245','Mixed/Unclassified','On examination, he limps, favouring the left leg. Back movements are restricted by
pain, with a positive nerve tension stretch sign on the left on straight leg raising. He
can stand and walk on his heels but is unable to stand or walk on his toes using his
left leg. There is no muscle wasting. He has diminished sensation of the outer two toes
extending to the sole of the foot. He has normal symmetrical knee jerks, but the left
ankle jerk is diminished compared to the right. Which one of the following is the most
likely diagnosis?','{"A":"Stress fracture of an osteoporotic lumbar vertebra.","B":"Spondylolysis of L5 with a posterior neural arch defect.","C":"Spondylolisthesis of L4 vertebral body forward on LS.","D":"Prolapse of a lumbosacral (L5/S1) intervertebral disc.","E":"Exacerbation of facet joint arthritis.\n\nMCQ 3.053"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[245],"source_qid":"3.051","duplicate_group_id":"exact-63dba767b3e4","duplicate_sources":[{"record_id":"b76a7c605c194f014d54","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":245,"source_qid":"3.051"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"b76a7c605c194f014d54","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":245,"supporting_pages":[245],"source_qid":"3.051","domain_hint":"Mixed/Unclassified","stem":"On examination, he limps, favouring the left leg. Back movements are restricted by\npain, with a positive nerve tension stretch sign on the left on straight leg raising. He\ncan stand and walk on his heels but is unable to stand or walk on his toes using his\nleft leg. There is no muscle wasting. He has diminished sensation of the outer two toes\nextending to the sole of the foot. He has normal symmetrical knee jerks, but the left\nankle jerk is diminished compared to the right. Which one of the following is the most\nlikely diagnosis?","options":{"A":"Stress fracture of an osteoporotic lumbar vertebra.","B":"Spondylolysis of L5 with a posterior neural arch defect.","C":"Spondylolisthesis of L4 vertebral body forward on LS.","D":"Prolapse of a lumbosacral (L5/S1) intervertebral disc.","E":"Exacerbation of facet joint arthritis.\n\nMCQ 3.053"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"63dba767b3e472b2d0bd4896b54061bcfa7e1777","duplicate_group_id":"exact-63dba767b3e4","duplicate_sources":[{"record_id":"b76a7c605c194f014d54","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":245,"source_qid":"3.051"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
