INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f501a091f97e6993adbe','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','245','Mixed/Unclassified','a Australian Medical Council
; Section 3 -— Adult Health and Aged Care
MCQ 3.051
An 80-year-old woman falls on her shoulder
and is subsequently unable to abduct her
arm. The X-ray of her shoulder is shown.
Which one of the following is the most likely
diagnosis?','{"A":"Acromioclavicular joint subluxation. ,","B":"Exacerbation of calcific rotator cuff\n\ntendonitis. ;","C":"Adhesive capsulitis of the glenohumeral ii\njoint. ¥","D":"Fractured surgical neck of the humerus. -","E":"Anteroinferior dislocation of the humerus.\n\nMCQ 3.052\n\nA 45-year-old man presents with an episode of acute low back pain following a lifting\nstrain at work. The pain radiates into the left buttock and down the back of the leg to\nthe foot, and is associated with pins and needles in the same distribution. He has no\npast history of back problems.\n\nOn examination, he limps, favouring the left leg. Back movements are restricted by\npain, with a positive nerve tension stretch sign on the left on straight leg raising. He\ncan stand and walk on his heels but is unable to stand or walk on his toes using his\nleft leg. There is no muscle wasting. He has diminished sensation of the outer two toes\nextending to the sole of the foot. He has normal symmetrical knee jerks, but the left\nankle jerk is diminished compared to the right. Which one of the following is the most\nlikely diagnosis?\n\nA. Stress fracture of an osteoporotic lumbar vertebra.\n\nB. Spondylolysis of L5 with a posterior neural arch defect.\n\nC. Spondylolisthesis of L4 vertebral body forward on LS.\n\nD. Prolapse of a lumbosacral (L5/S1) intervertebral disc.\n\nE. Exacerbation of facet joint arthritis.\n\nMCQ 3.053\n\nA 45-year-old farmer presents with an open (compound) fracture of the tibia due to\na rollover tractor injury. Which one of the following is the most important treatment\nmodality for prevention of infection?\n\nA. Immediate broad spectrum prophylactic antibiotics in large doses.\n\nB. Immediate and complete surgical debridement of the wound.\n\nC. Immediate anatomical reduction.\n\nD. Avoidance of the use of internal fixation.\n\nE. Limb elevation and adequate nutrition.\n\n227"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.051","duplicate_group_id":"exact-6cad8a9d4c02","duplicate_sources":[{"record_id":"f501a091f97e6993adbe","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":245,"source_qid":"3.051"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"f501a091f97e6993adbe","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":245,"source_qid":"3.051","domain_hint":"Mixed/Unclassified","stem":"a Australian Medical Council\n; Section 3 -— Adult Health and Aged Care\nMCQ 3.051\nAn 80-year-old woman falls on her shoulder\nand is subsequently unable to abduct her\narm. The X-ray of her shoulder is shown.\nWhich one of the following is the most likely\ndiagnosis?","options":{"A":"Acromioclavicular joint subluxation. ,","B":"Exacerbation of calcific rotator cuff\n\ntendonitis. ;","C":"Adhesive capsulitis of the glenohumeral ii\njoint. ¥","D":"Fractured surgical neck of the humerus. -","E":"Anteroinferior dislocation of the humerus.\n\nMCQ 3.052\n\nA 45-year-old man presents with an episode of acute low back pain following a lifting\nstrain at work. The pain radiates into the left buttock and down the back of the leg to\nthe foot, and is associated with pins and needles in the same distribution. He has no\npast history of back problems.\n\nOn examination, he limps, favouring the left leg. Back movements are restricted by\npain, with a positive nerve tension stretch sign on the left on straight leg raising. He\ncan stand and walk on his heels but is unable to stand or walk on his toes using his\nleft leg. There is no muscle wasting. He has diminished sensation of the outer two toes\nextending to the sole of the foot. He has normal symmetrical knee jerks, but the left\nankle jerk is diminished compared to the right. Which one of the following is the most\nlikely diagnosis?\n\nA. Stress fracture of an osteoporotic lumbar vertebra.\n\nB. Spondylolysis of L5 with a posterior neural arch defect.\n\nC. Spondylolisthesis of L4 vertebral body forward on LS.\n\nD. Prolapse of a lumbosacral (L5/S1) intervertebral disc.\n\nE. Exacerbation of facet joint arthritis.\n\nMCQ 3.053\n\nA 45-year-old farmer presents with an open (compound) fracture of the tibia due to\na rollover tractor injury. Which one of the following is the most important treatment\nmodality for prevention of infection?\n\nA. Immediate broad spectrum prophylactic antibiotics in large doses.\n\nB. Immediate and complete surgical debridement of the wound.\n\nC. Immediate anatomical reduction.\n\nD. Avoidance of the use of internal fixation.\n\nE. Limb elevation and adequate nutrition.\n\n227"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"6cad8a9d4c02419c70fba65669083b9920a1b937","duplicate_group_id":"exact-6cad8a9d4c02","duplicate_sources":[{"record_id":"f501a091f97e6993adbe","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":245,"source_qid":"3.051"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
