INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('bed1709a5233c7ef675d','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','247','Mixed/Unclassified','Australian Medical Council
Section 3 — Adult Health and Aged Care
MCQ 3.057
A 30-year-old man presents in the Emergency Department and is found to have an
anterior dislocation of the right shoulder. This is his fifth presentation with this problem
in the past six months. This presentation was precipitated by overbalancing when
reaching for a blanket on a high shelf. The other four were sustained during games of
Rugby. Which one of the following is the most appropriate immediate management
of this patient?
Injection of sclerosants into the joint.
Injection of steroids into the joint.
. An orthosis to prevent future dislocation.
Shoulder strapping.
Reduction in the Emergency Department.
TTMOQ2>
MCQ 3.058
A young man presents to the emergency department
after injuring his shoulder in a fall. His X-ray is shown.
Testing motor function by resisted isometric contraction
of which one of the following muscles would be most
likely to confirm the presence of an associated nerve
injury?
Latissimus dorsi.
Pectoralis major.
. Trapezius.
Serratus anterior.
Deltoid.
TOQOF>
MCQ 3.059
An 18-year-old youth has twisted his knee
playing cricket today. His knee is painful but not
swollen. His X-ray is shown. In assessing the X-ray
findings, after physical examination, which one
of the following is the most appropriate next
investigation?','{"A":"X-ray of the other knee.","B":"Magnetic resonance imaging (MRI) scan of\nthe affected knee.","C":"Computed tomogram of the affected knee.","D":"Arthroscopy.","E":"Operative patellectomy."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.057","duplicate_group_id":"exact-5c844d20abdd","duplicate_sources":[{"record_id":"bed1709a5233c7ef675d","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":247,"source_qid":"3.057"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"bed1709a5233c7ef675d","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":247,"source_qid":"3.057","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3 — Adult Health and Aged Care\nMCQ 3.057\nA 30-year-old man presents in the Emergency Department and is found to have an\nanterior dislocation of the right shoulder. This is his fifth presentation with this problem\nin the past six months. This presentation was precipitated by overbalancing when\nreaching for a blanket on a high shelf. The other four were sustained during games of\nRugby. Which one of the following is the most appropriate immediate management\nof this patient?\nInjection of sclerosants into the joint.\nInjection of steroids into the joint.\n. An orthosis to prevent future dislocation.\nShoulder strapping.\nReduction in the Emergency Department.\nTTMOQ2>\nMCQ 3.058\nA young man presents to the emergency department\nafter injuring his shoulder in a fall. His X-ray is shown.\nTesting motor function by resisted isometric contraction\nof which one of the following muscles would be most\nlikely to confirm the presence of an associated nerve\ninjury?\nLatissimus dorsi.\nPectoralis major.\n. Trapezius.\nSerratus anterior.\nDeltoid.\nTOQOF>\nMCQ 3.059\nAn 18-year-old youth has twisted his knee\nplaying cricket today. His knee is painful but not\nswollen. His X-ray is shown. In assessing the X-ray\nfindings, after physical examination, which one\nof the following is the most appropriate next\ninvestigation?","options":{"A":"X-ray of the other knee.","B":"Magnetic resonance imaging (MRI) scan of\nthe affected knee.","C":"Computed tomogram of the affected knee.","D":"Arthroscopy.","E":"Operative patellectomy."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"5c844d20abdd81e04f1191ba92eeb45855c365ad","duplicate_group_id":"exact-5c844d20abdd","duplicate_sources":[{"record_id":"bed1709a5233c7ef675d","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":247,"source_qid":"3.057"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visu