INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('158896c2578c16f35f25','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','249','Mixed/Unclassified','Australian Medical Council
Section 3 — Adult Health and Aged Care
MCQ 3.063
A 58-year-old male smoker presents to you with back pain. His X-ray and spinal
computed tomography (CT) showed osteoporotic lower thoracic vertebral fractures
and osteopenia without any destructive or erosive features to suggest a malignancy.
Subsequent bone mineral density studies are consistent with spinal osteoporosis.
His body mass index (BMI) is 29, he is hypertensive on a thiazide diuretic, and on a
weight-reducing, low-calorie diet for Type 2 diabetes mellitus. His past medical history
includes an inguinal hernia operation, and a localised lymphoma in the groin treated
with radiation therapy 10 years ago. Which one of the following is the most likely
reason for his osteoporosis?
A. Thiazide diuretic.
B. Idiopathic (senile) osteoporosis.
C. Multiple myeloma.
D. Hypogonadism.
E. Diabetes mellitus.
MCQ 3.064
A 61-year-old man with a history of alcoholic cirrhosis and gout presents to the
Emergency Department with acute pain and swelling in the right knee joint, with fever
and chills for the past 48 hours. His temperature is 39°C and he has a tender and swollen
knee joint. Investigations reveal polymorphonuclear leucocytosis, with elevated urea
and creatinine levels. Which one of the following is the most appropriate immediate
management?
A. Joint aspiration.
B. Colchicine every two hours until pain settles down.
C. X-ray of the knee.
D. Intravenous gentamicin.
E. Urgent urate levels.
MCQ 3.065
A 75-year-old woman is admitted with a displaced subcapital fracture of the neck
of her right femur sustained from a fall. In counselling the patient about treatment
options and possible complications, which one of the following is the most important
complication to discuss?','{"A":"Avascular necrosis (AVN) of the femoral head.","B":"Malunion of the fracture site.","C":"Nonunion of the fracture site.","D":"Infection following open treatment of the fracture.","E":"Long-term risk of osteoarthritis.\n231"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[249],"source_qid":"3.063","duplicate_group_id":"exact-72046e0bcb03","duplicate_sources":[{"record_id":"158896c2578c16f35f25","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":249,"source_qid":"3.063"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','high','{"record_id":"158896c2578c16f35f25","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":249,"supporting_pages":[249],"source_qid":"3.063","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3 — Adult Health and Aged Care\nMCQ 3.063\nA 58-year-old male smoker presents to you with back pain. His X-ray and spinal\ncomputed tomography (CT) showed osteoporotic lower thoracic vertebral fractures\nand osteopenia without any destructive or erosive features to suggest a malignancy.\nSubsequent bone mineral density studies are consistent with spinal osteoporosis.\nHis body mass index (BMI) is 29, he is hypertensive on a thiazide diuretic, and on a\nweight-reducing, low-calorie diet for Type 2 diabetes mellitus. His past medical history\nincludes an inguinal hernia operation, and a localised lymphoma in the groin treated\nwith radiation therapy 10 years ago. Which one of the following is the most likely\nreason for his osteoporosis?\nA. Thiazide diuretic.\nB. Idiopathic (senile) osteoporosis.\nC. Multiple myeloma.\nD. Hypogonadism.\nE. Diabetes mellitus.\nMCQ 3.064\nA 61-year-old man with a history of alcoholic cirrhosis and gout presents to the\nEmergency Department with acute pain and swelling in the right knee joint, with fever\nand chills for the past 48 hours. His temperature is 39°C and he has a tender and swollen\nknee joint. Investigations reveal polymorphonuclear leucocytosis, with elevated urea\nand creatinine levels. Which one of the following is the most appropriate immediate\nmanagement?\nA. Joint aspiration.\nB. Colchicine every two hours until pain settles down.\nC. X-ray of the knee.\nD. Intravenous gentamicin.\nE. Urgent urate levels.\nMCQ 3.065\nA 75-year-old woman is admitted with a displaced subcapital fracture of the neck\nof her right femur sustained from a fall. In counselling the patient about treatment\noptions and possible complications, which one of the following is the most important\ncomplication to discuss?","options":{"A":"Avascular necrosis (AVN) of the femoral head.","B":"Malunion of the fracture site.","C":"Nonunion of the fracture site.","D":"Infection following open treatment of the fracture.","E":"Long-term risk of osteoarthritis.\n231"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","diabetes","management","therapy","treatment"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"72046e0bcb033b93df5fe288a0234e0286a602f9","duplicate_group_id":"exact-72046e0bcb0