INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a85f77d6212d066c5cea','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','258','Mixed/Unclassified','Australian Medical Council
| Section 3 — Adult Health and Aged Care
MCQ 3.081
Which one of the following joint injuries is most likely to produce an arterial injury?','{"A":"Anterior dislocation of the shoulder.","B":"Lateral dislocation of the ankle.","C":"Posterior dislocation of the knee.","D":"Anterior dislocation of the elbow.","E":". Posterior dislocation of the hip.\n\nA 73-year-old woman with chronic obstructive\npulmonary disease (COPD), and a long history\nof cigarette smoking, is admitted with a history\nof fever, cough with yellow sputum, and chills\nfor the past five days. On examination her\ntemperature is 38°C, BP is 120/70mmHg, and\npulse 98/min. There is bilateral wheezing. Her\nchest X-ray is shown. Which one of the following\nis the most appropriate next step in diagnosis?\nA. Sputum microscopy staining for\n\nacid-fast bacilli.\n\nSputum microscopy with Gram stain.\n\n. Bronchoscopy.\n\nSputum microscopy for Aspergillus fumigatus.\nComputed tomographic pulmonary angiogram (CTPA).\n\nTMTMOQO®\n\nMCQ 3.083\n\nA 66-year-old man presents to the Emergency Department following three episodes\nof mid-sternal chest discomfort, each lasting between three and five minutes, over\nthe last 72 hours. The discomfort came on at rest and was relieved after two puffs of\nglycery| trinitrate spray on each occasion. Two years ago he had been commenced\non metoprolol following an episode of exertional chest pain. He stopped smoking\ntwo years ago, had well-controlled hypertension and was on treatment for\nhypercholesterolaemia. A recent plasma total cholesterol was 5.5mmol/L. His drug\n\ntherapy was:\n\nAspirin 100mg mane\nPerindopril/indapamide 5/1.25mg mane\nMetoprolol 50mg b.d.\nAtorvastatin 20mg mane\n\nAn ECG showed left ventricular hypertrophy and lateral T-wave flattening. Serum\ntroponin was normal. Which one of the following is the most appropriate next step in\nmanagement?"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.081","duplicate_group_id":"exact-0601ca4c7922","duplicate_sources":[{"record_id":"a85f77d6212d066c5cea","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":258,"source_qid":"3.081"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"a85f77d6212d066c5cea","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":258,"source_qid":"3.081","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\n| Section 3 — Adult Health and Aged Care\nMCQ 3.081\nWhich one of the following joint injuries is most likely to produce an arterial injury?","options":{"A":"Anterior dislocation of the shoulder.","B":"Lateral dislocation of the ankle.","C":"Posterior dislocation of the knee.","D":"Anterior dislocation of the elbow.","E":". Posterior dislocation of the hip.\n\nA 73-year-old woman with chronic obstructive\npulmonary disease (COPD), and a long history\nof cigarette smoking, is admitted with a history\nof fever, cough with yellow sputum, and chills\nfor the past five days. On examination her\ntemperature is 38°C, BP is 120/70mmHg, and\npulse 98/min. There is bilateral wheezing. Her\nchest X-ray is shown. Which one of the following\nis the most appropriate next step in diagnosis?\nA. Sputum microscopy staining for\n\nacid-fast bacilli.\n\nSputum microscopy with Gram stain.\n\n. Bronchoscopy.\n\nSputum microscopy for Aspergillus fumigatus.\nComputed tomographic pulmonary angiogram (CTPA).\n\nTMTMOQO®\n\nMCQ 3.083\n\nA 66-year-old man presents to the Emergency Department following three episodes\nof mid-sternal chest discomfort, each lasting between three and five minutes, over\nthe last 72 hours. The discomfort came on at rest and was relieved after two puffs of\nglycery| trinitrate spray on each occasion. Two years ago he had been commenced\non metoprolol following an episode of exertional chest pain. He stopped smoking\ntwo years ago, had well-controlled hypertension and was on treatment for\nhypercholesterolaemia. A recent plasma total cholesterol was 5.5mmol/L. His drug\n\ntherapy was:\n\nAspirin 100mg mane\nPerindopril/indapamide 5/1.25mg mane\nMetoprolol 50mg b.d.\nAtorvastatin 20mg mane\n\nAn ECG showed left ventricular hypertrophy and lateral T-wave flattening. Serum\ntroponin was normal. Which one of the following is the most appropriate next step in\nmanagement?"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"0601ca4c7922c2ef865d54e7f44813a325f74e36","duplicate_group_id":"exact-0601ca4c7922","duplicate_sources":[{"record_id":"a85f77d6212d066c5cea","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":258,"source_qid":"3.081"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visua