INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c0dd01007362b90814b8','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','261','Mixed/Unclassified','Australian Medical Council
Section 3 — Adult Health and Aged Care
MCQ 3.086
A 60-year-old man had an appendicectomy for acute appendicitis. On the 10th
postoperative day, he had sudden pain in the left chest with haemoptysis and a left
pleural friction rub could be heard. The clinical diagnosis is confirmed by imaging
and he responds well initially to a course of treatment. In counselling him regarding
prognosis, which one of the following is most likely to be the expected eventual
outcome in this case?
Recurrent episodes of chest pain.
Complete recovery.
. Left empyema.
Pulmonary fibrosis.
Severe prolonged dyspnoea.
MOORP>
MCQ 3.087
One week after an oesophagectomy for carcinoma of the cardia, a 73-year-
old man complains of constant left-sided chest pain. On examination the
patient looks unwell, with a temperature of 38.5°C, BP of 110/70mmHg and pulse
130/min, which is irregular. There is dullness to the left chest base. The abdomen is soft
and non-tender. Which one of the following is the most likely cause of the problem?
Pulmonary embolus.
Pneumonia.
. Anastomotic leak.
Subphrenic abscess.
Myocardial infarction.
MOOR >
MCQ 3.088
A 27-year-old man is brought to the Emergency Department after a motor vehicle
crash. He is able to provide a history and states that, as a restrained front seat
passenger, he was injured on the left side of his chest when the car in which he was
travelling was hit on the left side. He has severe pain in the left side of his chest and
cannot take deep breaths. On examination his BP is 130/70mmHg and pulse 110/
min. As the examination proceeds his breathing becomes laboured. He becomes
cyanosed and his neck veins bulge. Breath sounds are diminished on the left. Which
one of the following is the most likely diagnosis?','{"A":"Cardiac tamponade from haemopericardium.\nPulmonary contusion.","B":". Tension pneumothorax.","C":"Flail chest.","D":"Haemothorax.","E":"mOQP>"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[261],"source_qid":"3.086","duplicate_group_id":"exact-16a58aea185f","duplicate_sources":[{"record_id":"c0dd01007362b90814b8","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":261,"source_qid":"3.086"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"c0dd01007362b90814b8","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":261,"supporting_pages":[261],"source_qid":"3.086","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3 — Adult Health and Aged Care\nMCQ 3.086\nA 60-year-old man had an appendicectomy for acute appendicitis. On the 10th\npostoperative day, he had sudden pain in the left chest with haemoptysis and a left\npleural friction rub could be heard. The clinical diagnosis is confirmed by imaging\nand he responds well initially to a course of treatment. In counselling him regarding\nprognosis, which one of the following is most likely to be the expected eventual\noutcome in this case?\nRecurrent episodes of chest pain.\nComplete recovery.\n. Left empyema.\nPulmonary fibrosis.\nSevere prolonged dyspnoea.\nMOORP>\nMCQ 3.087\nOne week after an oesophagectomy for carcinoma of the cardia, a 73-year-\nold man complains of constant left-sided chest pain. On examination the\npatient looks unwell, with a temperature of 38.5°C, BP of 110/70mmHg and pulse\n130/min, which is irregular. There is dullness to the left chest base. The abdomen is soft\nand non-tender. Which one of the following is the most likely cause of the problem?\nPulmonary embolus.\nPneumonia.\n. Anastomotic leak.\nSubphrenic abscess.\nMyocardial infarction.\nMOOR >\nMCQ 3.088\nA 27-year-old man is brought to the Emergency Department after a motor vehicle\ncrash. He is able to provide a history and states that, as a restrained front seat\npassenger, he was injured on the left side of his chest when the car in which he was\ntravelling was hit on the left side. He has severe pain in the left side of his chest and\ncannot take deep breaths. On examination his BP is 130/70mmHg and pulse 110/\nmin. As the examination proceeds his breathing becomes laboured. He becomes\ncyanosed and his neck veins bulge. Breath sounds are diminished on the left. Which\none of the following is the most likely diagnosis?","options":{"A":"Cardiac tamponade from haemopericardium.\nPulmonary contusion.","B":". Tension pneumothorax.","C":"Flail chest.","D":"Haemothorax.","E":"mOQP>"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"16a58aea185f1e02041081a69b89854921a96123","duplicate_group_id":"exact-16a58aea185f","duplicate_sources":[{"record_id":"c0dd01007362b90814b8","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (