e of intravenous antibiotics and review after several hours.\nB. Arrange for a computed tomogram (CT) of the abdomen.\nC. Arrange an ultrasound examination of the lower abdomen and pelvis.\nD. Arrange for a gynaecological consultation.\nE. Book the patient for emergency surgery.\n\n|"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"ee831648684f3d98249282c55b5fbc1f55ac55be","duplicate_group_id":"exact-ee831648684f","duplicate_sources":[{"record_id":"f52bfc8d004af76c59c1","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":266,"source_qid":"3.098"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
