INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a5d17ca5ad62d072ae3e','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','268','Mixed/Unclassified','Australian Medical Council 4
Section 3— Adult Health and Aged Care 3
MCQ 3.104
You are about to perform a femoral venepuncture. You should be aware that the
structures in the groin under the inguinal ligament from medial to lateral are:','{"A":"lacunar ligament, femoral artery, femoral vein, femoral nerve.","B":"lacunar ligament, femoral vein, femoral artery, femoral nerve.","C":"lacunar ligament, femoral vein, femoral nerve, femoral artery.","D":"femoral vein, femoral artery, femoral nerve, lacunar ligament.","E":"lacunar ligament, femoral vein, femoral nerve, femoral artery.\nMCQ 3.105\nA 35-year-old man presents with a five-year history of dysphagia. Initially his problem\nwas limited to slow eating but more recently he has found that food tends to stick\nand he gets nocturnal regurgitation. He has not experienced any change in weight.\nWhich one of the following is the most likely diagnosis?\nA. Peptic oesophagedI stricture.\nB. Carcinoma of the oesophagus.\nC. Achalasia of the oesophagus.\nD. Pharyngeal pouch (Zenker diverticulum).\nE. Oesophageal diverticulum.\nMCQ 3.106 )\nA 58-year-old man is being investigated for a four-month history of increasing\ndysphagia. At endoscopy he is found to have in the lower oesophagus a 10cm\nsegment of columnar-lined epithelium with an ulcerating lesion in the middle of\nthis area. There is some narrowing of the lumen at this site. Biopsies of the ulcer and\nsurrounding tissue show granulation tissue only. Which one of the following is the most\nappropriate plan of management?\nA. Start on a course of a proton pump inhibitor (PPI).\nB. Prescribe a prokinetic agent (e.g. domperidone).\nC. Repeat the endoscopy and biopsy.\nD. Arrange an endoscopic ultrasound examination.\nE. Arrange a dilatation of the stricture.\nMCQ 3.107\nA 65-year-old woman presents with a one-month history of tiredness, lassitude and\nincreasing pain in the upper abdomen, which goes through to her back. She has\nlost about 10kg in weight. Over the last four days she has noticed that her urine has\nbeen dark and frothy and her faeces are pale. Despite the weight loss, she is still\nobese and no abnormalities are found on examination of the abdomen. Diagnostic\ninvestigations include ultrasonography of the upper abdomen. Which one of the\nfollowing is most likely to be shown by the ultrasound?\n\n250 be"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.104","duplicate_group_id":"exact-3be9aeb49578","duplicate_sources":[{"record_id":"a5d17ca5ad62d072ae3e","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":268,"source_qid":"3.104"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"a5d17ca5ad62d072ae3e","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":268,"source_qid":"3.104","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council 4\nSection 3— Adult Health and Aged Care 3\nMCQ 3.104\nYou are about to perform a femoral venepuncture. You should be aware that the\nstructures in the groin under the inguinal ligament from medial to lateral are:","options":{"A":"lacunar ligament, femoral artery, femoral vein, femoral nerve.","B":"lacunar ligament, femoral vein, femoral artery, femoral nerve.","C":"lacunar ligament, femoral vein, femoral nerve, femoral artery.","D":"femoral vein, femoral artery, femoral nerve, lacunar ligament.","E":"lacunar ligament, femoral vein, femoral nerve, femoral artery.\nMCQ 3.105\nA 35-year-old man presents with a five-year history of dysphagia. Initially his problem\nwas limited to slow eating but more recently he has found that food tends to stick\nand he gets nocturnal regurgitation. He has not experienced any change in weight.\nWhich one of the following is the most likely diagnosis?\nA. Peptic oesophagedI stricture.\nB. Carcinoma of the oesophagus.\nC. Achalasia of the oesophagus.\nD. Pharyngeal pouch (Zenker diverticulum).\nE. Oesophageal diverticulum.\nMCQ 3.106 )\nA 58-year-old man is being investigated for a four-month history of increasing\ndysphagia. At endoscopy he is found to have in the lower oesophagus a 10cm\nsegment of columnar-lined epithelium with an ulcerating lesion in the middle of\nthis area. There is some narrowing of the lumen at this site. Biopsies of the ulcer and\nsurrounding tissue show granulation tissue only. Which one of the following is the most\nappropriate plan of management?\nA. Start on a course of a proton pump inhibitor (PPI).\nB. Prescribe a prokinetic agent (e.g. domperidone).\nC. Repeat the endoscopy and biopsy.\nD. Arrange an endoscopic ultrasound examination.\nE. Arrange a dilatation of the stricture.\nMCQ 3.107\nA 65-year-old woman presents with a one-month history of tiredness, lassitude and\nincreasing pain in the upper abdomen, which goes through to her back. She has\nlost about 10kg in weight. Over the last four days she has noticed that her urine has\nbeen dark and frothy and her faeces are pale. Despite the weight loss, she is still\nobese and no abnormalities are found on examination of the abdomen. Diagnostic\ninvestigations include ultrasonography of the upper abdomen. Which one of the\nfollowing is most likely to be shown by the ultrasound?\n\n250 be"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_m