tween the xiphisternum and the umbilicus. This lump is\nstill palpable when the patient tenses his abdominal recti. Which one of the following\nis the most likely cause of his problem?","options":{"A":"Paraumbilical hernia.","B":"Spigelian hernia.","C":"Epigastric hernia.","D":"Infected epidermoid cyst.","E":"Torsion of a lipoma.\nMCQ 3.116"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"cfc4ce8cb51a9ddb759ac50a58f34994125cd196","duplicate_group_id":"exact-cfc4ce8cb51a","duplicate_sources":[{"record_id":"26ef7dc4a6b1e913ee0b","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":271,"source_qid":"3.115"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
