INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d5a0a2a5380ea3bf6c0c','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','274','Mixed/Unclassified','Australian Medical Council
MCQ 3.123
A 23-year-old woman presents requesting disease-inheritance risk counselling. She
was diagnosed at age 13 with familial adenomatous polyposis (FAP) and had a
total colectomy and ileorectal anastomosis. She has had regular upper and lower
gastrointestinal endoscopy since and was clear of polyps on last review. Her 50-year-
old mother was affected and treated similarly. Your patient is about to be married;
her fiancé does not have the condition. Which one of the following is the probability
of one of her children being affected with FAP?','{"A":"SECTION 3: ADULT HEALTH AND AGED CARE","B":"Medicine and Surgery","C":"3.124-3.137\nSystem 08","D":"BREAST\nENDOCRINE SYSTEM","E":"May include: breast, pituitary, thyroid, parathyroid, calcium, bone metabolism,\nadrenal, diabetes and pancreatic islets, gut hormones, neuroendocrine interactions,\nmetabolic responses to injury."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[274,275],"source_qid":"3.123","duplicate_group_id":"exact-124d5c53b74e","duplicate_sources":[{"record_id":"d5a0a2a5380ea3bf6c0c","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":274,"source_qid":"3.123"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"d5a0a2a5380ea3bf6c0c","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":274,"supporting_pages":[274,275],"source_qid":"3.123","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nMCQ 3.123\nA 23-year-old woman presents requesting disease-inheritance risk counselling. She\nwas diagnosed at age 13 with familial adenomatous polyposis (FAP) and had a\ntotal colectomy and ileorectal anastomosis. She has had regular upper and lower\ngastrointestinal endoscopy since and was clear of polyps on last review. Her 50-year-\nold mother was affected and treated similarly. Your patient is about to be married;\nher fiancé does not have the condition. Which one of the following is the probability\nof one of her children being affected with FAP?","options":{"A":"SECTION 3: ADULT HEALTH AND AGED CARE","B":"Medicine and Surgery","C":"3.124-3.137\nSystem 08","D":"BREAST\nENDOCRINE SYSTEM","E":"May include: breast, pituitary, thyroid, parathyroid, calcium, bone metabolism,\nadrenal, diabetes and pancreatic islets, gut hormones, neuroendocrine interactions,\nmetabolic responses to injury."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"124d5c53b74e30061f7f45b7cc79fa42956b1b38","duplicate_group_id":"exact-124d5c53b74e","duplicate_sources":[{"record_id":"d5a0a2a5380ea3bf6c0c","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":274,"source_qid":"3.123"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
