INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('effdecf846646e6a0a88','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','276','Mixed/Unclassified','Australian Medical Council GAS Se Sees
sSechions= AGU neatinandAgedCare =
Naanrrrree reer SSS SSS SSS SSSR,
MCQ 3.124
An 85-year-old woman presents with a history of a painless crusting red rash affecting
her left nipple which has been present for three months with progressive extension to
involve most of the nipple and areola. There was no associated nipple discharge and
no previous or family history of breast problems. Clinical examination of the breasts
was otherwise normal.
A punch biopsy under local anaesthesia is reported as showing intradermal large
clear Pagetoid cells, diagnosed as Paget disease of nipple — in-situ carcinoma.
Mammography and ultrasound show some nipple skin thickening and dilated ducts
affecting the left breast beneath the areola. No parenchymal mass or distortion is
identified otherwise in either breast or axillae. Which one of the following is the most
appropriate treatment?','{"A":"Breast-conserving wide local excision of the nipple and underlying area. |","B":"Total mastectomy.","C":"Local irradiation.","D":"Tamoxifen.","E":"Oophorectomy.\nMCQ 3.125\nA 50-year-old woman presents with a history of nipple inversion in the left breast\ndeveloping over a three month period. She is postmenopausal, and has no previous\nfamily history of breast problems.\nOn examination the left nipple is retracted and inverted. A 1.5cm firm lump is palpable\nbeneath and attached to the nipple and areola at 2 o''clock. The right breast is\nnormal and the lymph node areas of axillae and neck are clear. Mammogram and\nultrasound confirm the presence of a solid stellate lesion consistent with the clinical\nfindings in the left breast.\nA percutaneous core biopsy is done and reported as showing an invasive ductal\ncarcinoma of medium histologic grade without evidence of lymphatic or vascular\ninvasion. Chest X-ray is clear. Oestrogen and progesterone receptor status of\nthe tumour is positive. Which one of the following is the most appropriate initial\nmanagement of the breast lesion?\nA. Total mastectomy.\nB. Partial mastectomy.\nC. Radiation therapy.\nD. Tamoxifen.\nE. Aromatase inhibitor.\n\n258"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.124","duplicate_group_id":"exact-b629511efaad","duplicate_sources":[{"record_id":"effdecf846646e6a0a88","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":276,"source_qid":"3.124"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"effdecf846646e6a0a88","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":276,"source_qid":"3.124","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council GAS Se Sees\nsSechions= AGU neatinandAgedCare =\nNaanrrrree reer SSS SSS SSS SSSR,\nMCQ 3.124\nAn 85-year-old woman presents with a history of a painless crusting red rash affecting\nher left nipple which has been present for three months with progressive extension to\ninvolve most of the nipple and areola. There was no associated nipple discharge and\nno previous or family history of breast problems. Clinical examination of the breasts\nwas otherwise normal.\nA punch biopsy under local anaesthesia is reported as showing intradermal large\nclear Pagetoid cells, diagnosed as Paget disease of nipple — in-situ carcinoma.\nMammography and ultrasound show some nipple skin thickening and dilated ducts\naffecting the left breast beneath the areola. No parenchymal mass or distortion is\nidentified otherwise in either breast or axillae. Which one of the following is the most\nappropriate treatment?","options":{"A":"Breast-conserving wide local excision of the nipple and underlying area. |","B":"Total mastectomy.","C":"Local irradiation.","D":"Tamoxifen.","E":"Oophorectomy.\nMCQ 3.125\nA 50-year-old woman presents with a history of nipple inversion in the left breast\ndeveloping over a three month period. She is postmenopausal, and has no previous\nfamily history of breast problems.\nOn examination the left nipple is retracted and inverted. A 1.5cm firm lump is palpable\nbeneath and attached to the nipple and areola at 2 o''clock. The right breast is\nnormal and the lymph node areas of axillae and neck are clear. Mammogram and\nultrasound confirm the presence of a solid stellate lesion consistent with the clinical\nfindings in the left breast.\nA percutaneous core biopsy is done and reported as showing an invasive ductal\ncarcinoma of medium histologic grade without evidence of lymphatic or vascular\ninvasion. Chest X-ray is clear. Oestrogen and progesterone receptor status of\nthe tumour is positive. Which one of the following is the most appropriate initial\nmanagement of the breast lesion?\nA. Total mastectomy.\nB. Partial mastectomy.\nC. Radiation therapy.\nD. Tamoxifen.\nE. Aromatase inhibitor.\n\n258"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","treatment"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"b629511efaadde435368b7ff2d2a8d0eb823e8de","duplicate_group_id":"exact-b629511efaad","duplicate_sources":[{"record_id":"effdecf846646e6a0a88","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":276,"source_qid":"3.124"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.recor