INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('25a516570f91b99278cf','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','277','Mixed/Unclassified','E. rea = Australian Medical Council
- : Section 3 — Adult Health and Aged Care
MCQ 3.126
A 55-year-old woman had undergone a left modified radical mastectomy for breast
cancer five years earlier. She had been well and there had been no evidence
of recurrent disease or problems elsewhere until she presents with a firm mobile
swelling in the upper outer quadrant of her remaining right breast. The lump is 2cm in
diameter and has an ill-defined margin. Which one of the following is the most likely
diagnosis?','{"A":"Fibrocystic disease.","B":"Anew primary carcinoma.","C":"Metastasis from the original carcinoma.","D":"Fibroadenoma.","E":"Lipoma.\nMCQ 3.127\nA 45-year-old woman presents with a history of bilateral mastalgia and bilateral nipple\ndischarge with greenish-yellow staining of her brassiere over a six-month period. There\nis NO past or family history of breast problems. She has a past history of whiplash of the\nneck after a motor vehicle accident two years ago, now settled.\nOn examination she has a thick bilateral greenish-yellow discharge on periareolar\ncompression. The discharge is seen to come from multiple ducts on each nipple.\nNo mass or other abnormality is found. Mammography and ultrasound shows some\ndilatation of the main ducts behind the nipple, no focal asymmetry or mass is seen.\nWhich one of the following is the most likely diagnosis?\nA. Mammary duct ectasia.\nB. Occult invasive carcinoma breast.\nC. Lobular carcinoma-in-situ.\nD. Ductal carcinoma-in-situ.\nE. Fat necrosis.\nMCQ 3.128\nA 55-year-old woman has a history of left-sided nipple discharge over a five year\nperiod. On examination no breast lump is palpable. A greenish-yellow thick nipple\ndischarge can be expressed from multiple ducts of the left nipple. Cytology of the\ndischarge shows macrophages and debris without ductal cells. Mammography\nshows widespread linear and ovoid calcification ,as illustrated, in mediolateral oblique\nand craniocaudal views. Previous mammograms from two years and five years ago\nshowed similar features. Which one of the following is the most likely diagnosis?\n259"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.126","duplicate_group_id":"exact-7a6e89cc8e7e","duplicate_sources":[{"record_id":"25a516570f91b99278cf","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":277,"source_qid":"3.126"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"25a516570f91b99278cf","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":277,"source_qid":"3.126","domain_hint":"Mixed/Unclassified","stem":"E. rea = Australian Medical Council\n- : Section 3 — Adult Health and Aged Care\nMCQ 3.126\nA 55-year-old woman had undergone a left modified radical mastectomy for breast\ncancer five years earlier. She had been well and there had been no evidence\nof recurrent disease or problems elsewhere until she presents with a firm mobile\nswelling in the upper outer quadrant of her remaining right breast. The lump is 2cm in\ndiameter and has an ill-defined margin. Which one of the following is the most likely\ndiagnosis?","options":{"A":"Fibrocystic disease.","B":"Anew primary carcinoma.","C":"Metastasis from the original carcinoma.","D":"Fibroadenoma.","E":"Lipoma.\nMCQ 3.127\nA 45-year-old woman presents with a history of bilateral mastalgia and bilateral nipple\ndischarge with greenish-yellow staining of her brassiere over a six-month period. There\nis NO past or family history of breast problems. She has a past history of whiplash of the\nneck after a motor vehicle accident two years ago, now settled.\nOn examination she has a thick bilateral greenish-yellow discharge on periareolar\ncompression. The discharge is seen to come from multiple ducts on each nipple.\nNo mass or other abnormality is found. Mammography and ultrasound shows some\ndilatation of the main ducts behind the nipple, no focal asymmetry or mass is seen.\nWhich one of the following is the most likely diagnosis?\nA. Mammary duct ectasia.\nB. Occult invasive carcinoma breast.\nC. Lobular carcinoma-in-situ.\nD. Ductal carcinoma-in-situ.\nE. Fat necrosis.\nMCQ 3.128\nA 55-year-old woman has a history of left-sided nipple discharge over a five year\nperiod. On examination no breast lump is palpable. A greenish-yellow thick nipple\ndischarge can be expressed from multiple ducts of the left nipple. Cytology of the\ndischarge shows macrophages and debris without ductal cells. Mammography\nshows widespread linear and ovoid calcification ,as illustrated, in mediolateral oblique\nand craniocaudal views. Previous mammograms from two years and five years ago\nshowed similar features. Which one of the following is the most likely diagnosis?\n259"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"7a6e89cc8e7eac4add427b4d10d3500f3f222980","duplicate_group_id":"exact-7a6e89cc8e7e","duplicate_sources":[{"record_id":"25a516570f91b99278cf","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":277,"source_qid":"3.126"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.pr