INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6c099adbf4bf946abe7c','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','279','Mixed/Unclassified','Australian Medical Council
Section 3— Adult Health and Aged Care
. Addison disease from adrenal metastases.
. Ectopic autonomous adrenocorticotrophic hormone (ACTH) production.
. Cushing syndrome.
. Asquamous cell carcinoma of lung.
. A vasopressin (ADH)-secreting carcinoma of lung.
A 38-year-old woman, who had a subtotal thyroidectomy for hyperthyroidism due
to Graves disease eight years previously, presents with weight loss, tremor and heat
intolerance. The thyroid gland is not clinically enlarged. Her thyroid function tests
show her serum thyroid-stimulating hormone (TSH) is low and the triiodothyronine (T3)
and thyroxine (T4) are elevated. Which one of the following is the most appropriate
management?
Control with carbimazole and then perform total thyroidectomy.
Administer radioactive iodine after preparation with oral iodine treatment.
. Prescribe immunosuppressive treatment with azathioprine.
. Control with carbimazole and then administer radioactive iodine.
Provide short-term treatment with beta-blockers until remission occurs.
MOOQO2>
MCQ 3.131
A 68-year-old woman has had Type 2 diabetes mellitus for fifteen years and presents
for a routine quarterly review. She has hypertension, ischaemic heart disease,
congestive heart failure, renal impairment, proliferative retinopathy and peripheral
neuropathy. Her diabetic control was good until the past twelve months. She walks
1km three times per week.
Her current drug therapy is: gliciazide, pravastatin, lisinopril, metoprolol, aspirin and
a glyceryl trinitrate (GTN) patch. Her body mass index (BMI) is 32, BP is 142/78mmbg.
There is ++ proteinuria on dipstick analysis. Her HbA1. (glycated haemoglobin) is 11%
(5.0-6.5). Serum creatinine is 0.20mmol/L (0.06-0.12). Which one of the following is the
most appropriate next step in therapy?','{"A":"Commence insulin.","B":"Commence metformin.","C":"Commence rosiglitazone.","D":"Refer her to a dietitian.","E":"Advise increase in exercise.\n\nMCQ 3.132\n\nA previously well 55-year-old man presents with a two-month history of lethargy, thirst\nand weight loss of 3kg. He needs to pass urine frequently during the day and at least\ntwice a night but there is no hesitancy or dysuria. Which one of the following tests is\nmost likely to lead to a diagnosis?"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.131","duplicate_group_id":"exact-83a03d5da2e6","duplicate_sources":[{"record_id":"6c099adbf4bf946abe7c","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":279,"source_qid":"3.131"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"6c099adbf4bf946abe7c","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":279,"source_qid":"3.131","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3— Adult Health and Aged Care\n. Addison disease from adrenal metastases.\n. Ectopic autonomous adrenocorticotrophic hormone (ACTH) production.\n. Cushing syndrome.\n. Asquamous cell carcinoma of lung.\n. A vasopressin (ADH)-secreting carcinoma of lung.\nA 38-year-old woman, who had a subtotal thyroidectomy for hyperthyroidism due\nto Graves disease eight years previously, presents with weight loss, tremor and heat\nintolerance. The thyroid gland is not clinically enlarged. Her thyroid function tests\nshow her serum thyroid-stimulating hormone (TSH) is low and the triiodothyronine (T3)\nand thyroxine (T4) are elevated. Which one of the following is the most appropriate\nmanagement?\nControl with carbimazole and then perform total thyroidectomy.\nAdminister radioactive iodine after preparation with oral iodine treatment.\n. Prescribe immunosuppressive treatment with azathioprine.\n. Control with carbimazole and then administer radioactive iodine.\nProvide short-term treatment with beta-blockers until remission occurs.\nMOOQO2>\nMCQ 3.131\nA 68-year-old woman has had Type 2 diabetes mellitus for fifteen years and presents\nfor a routine quarterly review. She has hypertension, ischaemic heart disease,\ncongestive heart failure, renal impairment, proliferative retinopathy and peripheral\nneuropathy. Her diabetic control was good until the past twelve months. She walks\n1km three times per week.\nHer current drug therapy is: gliciazide, pravastatin, lisinopril, metoprolol, aspirin and\na glyceryl trinitrate (GTN) patch. Her body mass index (BMI) is 32, BP is 142/78mmbg.\nThere is ++ proteinuria on dipstick analysis. Her HbA1. (glycated haemoglobin) is 11%\n(5.0-6.5). Serum creatinine is 0.20mmol/L (0.06-0.12). Which one of the following is the\nmost appropriate next step in therapy?","options":{"A":"Commence insulin.","B":"Commence metformin.","C":"Commence rosiglitazone.","D":"Refer her to a dietitian.","E":"Advise increase in exercise.\n\nMCQ 3.132\n\nA previously well 55-year-old man presents with a two-month history of lethargy, thirst\nand weight loss of 3kg. He needs to pass urine frequently during the day and at least\ntwice a night but there is no hesitancy or dysuria. Which one of the following tests is\nmost likely to lead to a diagnosis?"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","diabetes","drug","hypertension","management","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"83a03d5da2e65f896a40ebc31694b03aecfa7e8a","duplicate_group_id":"exact-83a03d5da2e6","duplicate_sources":[{"record_id":"6c099adbf4bf946abe7c","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":279,"source_qid":"3.131"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
