INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9abb16a10ebc6305d649','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','284','Mixed/Unclassified','Australian Medical Council
section 3 — Adult Health and Aged Care
MCQ 3.138
A 25-year-old farm hand is involved in a motor car accident and sustains fractures of
the 10th and 11th ribs on his left side. He has no other injuries, and after three days in
hospital he is discharged. Five days after discharge he complains of abdominal pain
and, onreaching the emergency ward, is found to have a BP of 70 mmHg systolic and
a pulse rate of 120/min. The abdomen is a little distended and diffusely tender with
some rebound tenderness. Which one of the following is the most likely diagnosis?
Peritonitis from a perforation of the bowel.
Delayed rupture of the spleen.
. Secondary haemorrhage from a ruptured kidney.
Haemothorax.
Traumatic pancreatitis.
MOQR>
MCQ 3.139
A 50-year-old woman complains of lack of energy, tiredness and constipation over
the last several months. On examination she has a pallid complexion and a pulse rate
of 56/min. On investigation the blood film shows a macrocytic anaemia (Hb 100g/L)
with mild lymphocytosis. Which one of the following is the most likely diagnosis?
A. Pernicious anaemia.
B. Carcinoma of bowel.
C. Alcoholism and matnutrition.
D
E
. Primary hypothyroidism.
. Chronic lymphocytic leukaemia (CLL).
A 50-year-old woman presents with tiredness and pallor and is found to be anaemic.
Full blood examination shows the following features. Haemoglobin level is 48g/L with
a mildly increased reticulocyte count and normal platelet count. Red cells show
polychromasia. Haptoglobin level is decreased. Which one of the following features
favours the diagnosis of haemolytic anaemia rather than the anaemia of chronic
blood loss?','{"A":"Increased reticulocyte count.","B":"Decreased haptoglobin level.","C":"Anaemia of less than 50g/L.","D":"Presence of polychromasia.","E":"Normal platelet count."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[284],"source_qid":"3.138","duplicate_group_id":"exact-7e36182cf709","duplicate_sources":[{"record_id":"9abb16a10ebc6305d649","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":284,"source_qid":"3.138"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"9abb16a10ebc6305d649","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":284,"supporting_pages":[284],"source_qid":"3.138","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nsection 3 — Adult Health and Aged Care\nMCQ 3.138\nA 25-year-old farm hand is involved in a motor car accident and sustains fractures of\nthe 10th and 11th ribs on his left side. He has no other injuries, and after three days in\nhospital he is discharged. Five days after discharge he complains of abdominal pain\nand, onreaching the emergency ward, is found to have a BP of 70 mmHg systolic and\na pulse rate of 120/min. The abdomen is a little distended and diffusely tender with\nsome rebound tenderness. Which one of the following is the most likely diagnosis?\nPeritonitis from a perforation of the bowel.\nDelayed rupture of the spleen.\n. Secondary haemorrhage from a ruptured kidney.\nHaemothorax.\nTraumatic pancreatitis.\nMOQR>\nMCQ 3.139\nA 50-year-old woman complains of lack of energy, tiredness and constipation over\nthe last several months. On examination she has a pallid complexion and a pulse rate\nof 56/min. On investigation the blood film shows a macrocytic anaemia (Hb 100g/L)\nwith mild lymphocytosis. Which one of the following is the most likely diagnosis?\nA. Pernicious anaemia.\nB. Carcinoma of bowel.\nC. Alcoholism and matnutrition.\nD\nE\n. Primary hypothyroidism.\n. Chronic lymphocytic leukaemia (CLL).\nA 50-year-old woman presents with tiredness and pallor and is found to be anaemic.\nFull blood examination shows the following features. Haemoglobin level is 48g/L with\na mildly increased reticulocyte count and normal platelet count. Red cells show\npolychromasia. Haptoglobin level is decreased. Which one of the following features\nfavours the diagnosis of haemolytic anaemia rather than the anaemia of chronic\nblood loss?","options":{"A":"Increased reticulocyte count.","B":"Decreased haptoglobin level.","C":"Anaemia of less than 50g/L.","D":"Presence of polychromasia.","E":"Normal platelet count."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"7e36182cf7098fe4ed35736a53c80690d4bf9af1","duplicate_group_id":"exact-7e36182cf709","duplicate_sources":[{"record_id":"9abb16a10ebc6305d649","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":284,"source_qid":"3.138"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
