INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('dc6f853543e8f49e22b3','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','285','Mixed/Unclassified','A 25-year-old woman presented with a history of recurring nosebleeds and easy
bruising. Investigations confirmed the diagnosis of acute idiopathic (immune)
thrombocytopenic purpura (ITP). Her haemorrhagic tendency is best initially treated
with which one of the following?
Gamma globulin infusion.
Platelet transfusions.
. Plasma infusions.
Corticosteroids.
Azathioprine.
MOOP>
MCQ 3.142
A 26-year-old patient who had a splenectomy for trauma two years previously
presents with an upper respiratory tract infection. Which one of the following is the
most appropriate initial course of action?','{"A":"Institute a pneumococcal and meningococcal vaccination program.","B":"Prescribe a full course of penicillin.","C":"Admit the patient to the intensive care unit.","D":"Prescribe chest physiotherapy four times daily.","E":"Admit the patient for reversed barrier nursing.\n\nMCQ 3.143\n\nA 55-year-old woman, who recently returned from a holiday overseas, presents with\ntransient blurring of vision, thirty minutes ago, which has now completely resolved.\nShe looks well and is afebrile. Ophthalmological and neurological examinations are\nwithin normal limits. Her BP is 150/80mmbHg, pulse 78/min and regular. Her spleen is\npalpable 5cm below the costal margin. She has been a smoker (twenty cigarettes\ndaily) for the past thirty years. She is on a thiazide diuretic for hypertension.\n\nFull blood examination shows:\n\nHaemoglobin *180g/L (115-165)\nWCC (white cell count) = *14x109/L (4.0-11.0)\nRed cell count *8x10!2/L (3.8-5.8)\n\nPlatelets *800x10°/L (150-400)\n\nThe smear shows a normal leucocyte differential pattern.\nWhich one of the following is the most likely diagnosis?\n\nPlasmodium falciparum malaria.\nChronic myeloid leukaemia.\n\n. Secondary polycythaemia.\n\n. Polycythaemia rubra vera.\nMyelofibrosis.\n\nTTMOQP>\n\nAusiralian Medical Council\n\nSection 3 — Adult Health and Aged Care"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.141","duplicate_group_id":"exact-f25d47192a28","duplicate_sources":[{"record_id":"dc6f853543e8f49e22b3","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":285,"source_qid":"3.141"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"dc6f853543e8f49e22b3","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":285,"source_qid":"3.141","domain_hint":"Mixed/Unclassified","stem":"A 25-year-old woman presented with a history of recurring nosebleeds and easy\nbruising. Investigations confirmed the diagnosis of acute idiopathic (immune)\nthrombocytopenic purpura (ITP). Her haemorrhagic tendency is best initially treated\nwith which one of the following?\nGamma globulin infusion.\nPlatelet transfusions.\n. Plasma infusions.\nCorticosteroids.\nAzathioprine.\nMOOP>\nMCQ 3.142\nA 26-year-old patient who had a splenectomy for trauma two years previously\npresents with an upper respiratory tract infection. Which one of the following is the\nmost appropriate initial course of action?","options":{"A":"Institute a pneumococcal and meningococcal vaccination program.","B":"Prescribe a full course of penicillin.","C":"Admit the patient to the intensive care unit.","D":"Prescribe chest physiotherapy four times daily.","E":"Admit the patient for reversed barrier nursing.\n\nMCQ 3.143\n\nA 55-year-old woman, who recently returned from a holiday overseas, presents with\ntransient blurring of vision, thirty minutes ago, which has now completely resolved.\nShe looks well and is afebrile. Ophthalmological and neurological examinations are\nwithin normal limits. Her BP is 150/80mmbHg, pulse 78/min and regular. Her spleen is\npalpable 5cm below the costal margin. She has been a smoker (twenty cigarettes\ndaily) for the past thirty years. She is on a thiazide diuretic for hypertension.\n\nFull blood examination shows:\n\nHaemoglobin *180g/L (115-165)\nWCC (white cell count) = *14x109/L (4.0-11.0)\nRed cell count *8x10!2/L (3.8-5.8)\n\nPlatelets *800x10°/L (150-400)\n\nThe smear shows a normal leucocyte differential pattern.\nWhich one of the following is the most likely diagnosis?\n\nPlasmodium falciparum malaria.\nChronic myeloid leukaemia.\n\n. Secondary polycythaemia.\n\n. Polycythaemia rubra vera.\nMyelofibrosis.\n\nTTMOQP>\n\nAusiralian Medical Council\n\nSection 3 — Adult Health and Aged Care"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"f25d47192a2814bb7ae236fbadc53f5c560de94c","duplicate_group_id":"exact-f25d47192a28","duplicate_sources":[{"record_id":"dc6f853543e8f49e22b3","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":285,"source_qid":"3.141"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
